    "flavor": "මුහුදු පැළෑටි සහ කැපූ තණකොළ, රසවත් ඇමයිනෝ-අම්ල උමාමි රසය, අගදී සැහැල්ලු කහටක්. තේ වතුර කහ-කොළ පැහැයයි.",
